function formatTranslation(text=""){return escapeHtml(text).replace(/\[([^\]]{1,140})\]/g,'<span class="translation-clarification">[$1]</span>');}
function stripHtml(html=""){const doc=new DOMParser().parseFromString(html,"text/html");return doc.body.textContent||"";}
function formatTafsirReference(text){return escapeHtml(text).replace(/\((\d{1,3}:\d{1,3})\)/g,'<span class="tafsir-reference">($1)</span>');}
function isArabicPassage(text){const arabic=(text.match(/[\u0600-\u06FF]/g)||[]).length,latin=(text.match(/[A-Za-z]/g)||[]).length;return arabic>3&&arabic>latin;}
function formatTafsir(html=""){
  const doc=new DOMParser().parseFromString(html,"text/html"),sections=[];let section=null;
  const startSection=title=>{if(section&&(section.blocks.length||section.title))sections.push(section);section={title,blocks:[]};};
  [...doc.body.children].forEach(node=>{
    const text=(node.textContent||"").replace(/\s+/g," ").trim();if(!text)return;
    if(/^H[1-4]$/.test(node.tagName)){startSection(text);return;}
    if(!section)section={title:"Commentary",blocks:[]};
    section.blocks.push(isArabicPassage(text)?`<blockquote class="tafsir-arabic" lang="ar" dir="rtl"><span>Quranic passage</span>${escapeHtml(text)}</blockquote>`:`<p>${formatTafsirReference(text)}</p>`);
  });
  if(section&&(section.blocks.length||section.title))sections.push(section);
  if(!sections.length){const text=(doc.body.textContent||"").trim();if(text)sections.push({title:"Commentary",blocks:[`<p>${formatTafsirReference(text)}</p>`]});}
  return `<div class="tafsir-article">${sections.map((item,index)=>`<section class="tafsir-section"><div class="tafsir-section-number">${String(index+1).padStart(2,"0")}</div><div class="tafsir-section-copy"><h3>${escapeHtml(item.title||"Commentary")}</h3>${item.blocks.join("")}</div></section>`).join("")}</div>`;
}
function toArabicNumeral(number){return String(number).replace(/\d/g,d=>"٠١٢٣٤٥٦٧٨٩"[d]);}
