function parseTajweedWords(text){const stack=[],words=[];let runs=[],index=0;const push=character=>{if(/\s/.test(character)){if(runs.length){words.push(runs);runs=[];}return;}const rule=stack.at(-1)||null,last=runs.at(-1);if(last&&last.rule===rule)last.text+=character;else runs.push({rule,text:character});};while(index<text.length){if(text[index]==="["){const opening=text.slice(index).match(/^\[([a-z])(?::\d+)?\[/);if(opening){stack.push(opening[1]);index+=opening[0].length;continue;}const closing=text.indexOf("]",index+1);if(closing>index){[...text.slice(index+1,closing)].forEach(push);index=closing+1;continue;}}if(text[index]==="]"&&stack.length){stack.pop();index++;continue;}push(text[index]);index++;}if(runs.length)words.push(runs);return words;}
