function ayahVerseMarkup(verse){const surah=state.quran[verse.surah-1],active=verse.surah===state.currentSurah&&verse.numberInSurah===state.currentAyah,key=verseKey(verse.surah,verse.numberInSurah),completed=state.followedVerses.has(key),words=renderTajweedWords(state.tajweed&&verse.tajweedText?verse.tajweedText:verse.text,active,completed,key),bookmarked=isBookmarked(verse.surah,verse.numberInSurah),heading=verse.numberInSurah===1?`<header class="ayah-surah-heading"><span>${escapeHtml(surah?.name||"")} · ${verse.surah}</span><strong lang="ar" dir="rtl">${escapeHtml(surah?.arabicName||surah?.name||"")}</strong></header>`:"",study=state.translation==="study.easy";return `${heading}<article class="verse-card${active?" active":""}${completed?" recited-verse":""}${study?" easy-study-verse":""}" data-surah="${verse.surah}" data-ayah="${verse.numberInSurah}"><div class="verse-meta"><span class="ayah-reference">${verse.surah}:${verse.numberInSurah}</span><span class="now-label"><i></i>${state.mode==="practice"?"Practice":state.demo?"Demo":state.followLocked?"Following":"Current"}</span><div class="verse-actions"><button class="verse-action bookmark${bookmarked?" saved":""}" data-action="bookmark" aria-label="${bookmarked?"Remove bookmark":"Bookmark ayah"}" title="Bookmark"><svg viewBox="0 0 24 24"><path d="M6 4h12v16l-6-4-6 4V4Z"/></svg></button><button class="verse-action" data-action="study" aria-label="Compare translations and read tafsir" title="Ayah study">Study</button></div></div><p class="arabic" lang="ar" dir="rtl">${words} <span class="verse-end">﴿${toArabicNumeral(verse.numberInSurah)}﴾</span></p><p class="translation">${formatTranslation(verse.translation)}<span class="translation-source">${escapeHtml(translationSource())}</span></p></article>`;}
