function toggleBookmark(surah,ayah){const key=verseKey(surah,ayah);if(isBookmarked(surah,ayah))state.bookmarks=state.bookmarks.filter(x=>verseKey(x.surah,x.ayah)!==key);else state.bookmarks=[{surah,ayah,at:Date.now()},...state.bookmarks];saveLocal();renderSurah(state.currentSurah,state.currentAyah,{scroll:false,history:false});const saved=isBookmarked(surah,ayah),button=els.verses.querySelector(`.verse-card[data-surah="${surah}"][data-ayah="${ayah}"] .bookmark`);button?.classList.toggle("saved",saved);button?.setAttribute("aria-label",saved?"Remove bookmark":"Bookmark ayah");renderSavedItems();showToast(saved?"Ayah bookmarked":"Bookmark removed");}
