function runSearch(query){const raw=query.trim();if(!raw){els.searchResults.innerHTML='<p class="empty-state">Start typing to search all 6,236 verses.</p>';return;}const ref=raw.match(/^(\d{1,3})\s*:\s*(\d{1,3})$/);let results=[];if(ref){const surah=state.quran[Number(ref[1])-1],ayah=surah?.ayahs[Number(ref[2])-1];if(ayah)results=[{...ayah,surah:Number(ref[1]),surahName:surah.name}];}else{const arabic=normalizeArabic(raw),latin=normalizeLatin(raw);results=state.flatVerses.filter(verse=>(arabic&&arabic.length>1&&verse.normalized.includes(arabic))||(latin&&(`${verse.surah} ${verse.surahName}`.toLowerCase().includes(latin)||verse.english.includes(latin)))).slice(0,40);}els.searchResults.innerHTML=results.length?results.map(verse=>`<button class="search-result" data-surah="${verse.surah}" data-ayah="${verse.numberInSurah}"><span>${escapeHtml(verse.surahName)} · ${verse.surah}:${verse.numberInSurah}</span><strong lang="ar" dir="rtl">${escapeHtml(verse.text)}</strong><small>${escapeHtml(verse.translation)}</small></button>`).join(""):'<p class="empty-state">No exact matches yet. Try fewer words or a surah name.</p>';}
