els.increaseText.addEventListener("click",()=>{state.arabicSize=Math.min(3.2,state.arabicSize+.15);document.documentElement.style.setProperty("--arabic-size",`${state.arabicSize}rem`);localStorage.setItem("ayahflowTextSize",state.arabicSize);});els.decreaseText.addEventListener("click",()=>{state.arabicSize=Math.max(1.5,state.arabicSize-.15);document.documentElement.style.setProperty("--arabic-size",`${state.arabicSize}rem`);localStorage.setItem("ayahflowTextSize",state.arabicSize);});els.themeButton.addEventListener("click",()=>document.body.classList.toggle("light"));els.translationSelect.value=state.translation;els.translationSelect.addEventListener("change",()=>changeTranslation(els.translationSelect.value));
els.tajweedButton.disabled=true;els.quickTajweedButton.disabled=true;syncTajweedControls();els.tajweedLegend.hidden=!state.tajweed;els.tajweedButton.addEventListener("click",()=>{if(!state.tajweedAvailable)return;state.tajweed=!state.tajweed;localStorage.setItem("ayahflowTajweed",state.tajweed);syncTajweedControls();els.tajweedLegend.hidden=!state.tajweed;renderSurah(state.currentSurah,state.currentAyah,{scroll:false,history:false});});
els.verses.addEventListener("click",event=>{const action=event.target.closest("[data-action]"),card=event.target.closest(".verse-card"),mushafAyah=event.target.closest(".mushaf-ayah"),target=card||mushafAyah;if(!target)return;const surah=Number(target.dataset.surah)||state.currentSurah,ayah=Number(target.dataset.ayah);if(action?.dataset.action==="bookmark")toggleBookmark(surah,ayah);else if(action?.dataset.action==="study")openStudy(surah,ayah);else{stopDemo();state.practiceMarks=[];state.followLocked=false;state.followProgress=-1;state.pendingAdvanceKey=null;state.pendingAdvanceCount=0;renderSurah(surah,ayah);}});els.confirmCandidate.addEventListener("click",()=>{if(!state.candidate)return;lockOntoVerse(state.candidate,"Match confirmed");});els.clearTranscript.addEventListener("click",()=>{state.transcriptBuffer=[];els.transcriptText.textContent="";els.transcriptCard.hidden=true;els.transcriptCard.classList.remove("compact");state.candidate=null;});
els.searchButton.addEventListener("click",()=>{els.searchDialog.showModal();setTimeout(()=>els.searchInput.focus(),50);});els.searchInput.addEventListener("input",()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>runSearch(els.searchInput.value),120);});els.searchResults.addEventListener("click",event=>{const item=event.target.closest("[data-surah]");if(item)openVerseFromElement(item,els.searchDialog);});els.libraryButton.addEventListener("click",()=>{renderSavedItems();els.savedDialog.showModal();});els.savedItems.addEventListener("click",event=>{const item=event.target.closest("[data-surah]");if(item)openVerseFromElement(item,els.savedDialog);});document.querySelectorAll("[data-saved-tab]").forEach(button=>button.addEventListener("click",()=>{state.savedTab=button.dataset.savedTab;renderSavedItems();}));document.querySelectorAll("[data-close]").forEach(button=>button.addEventListener("click",()=>document.getElementById(button.dataset.close)?.close()));document.querySelectorAll("dialog").forEach(dialog=>dialog.addEventListener("click",event=>{if(event.target===dialog)dialog.close();}));
window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();state.deferredInstall=event;els.installButton.hidden=false;});els.installButton.addEventListener("click",async()=>{if(state.deferredInstall){state.deferredInstall.prompt();await state.deferredInstall.userChoice;state.deferredInstall=null;els.installButton.hidden=true;}else showToast("On iPhone, tap Share then ‘Add to Home Screen’. On Android, use your browser’s Install app option.");});window.addEventListener("appinstalled",()=>{els.installButton.hidden=true;showToast("AyahFlow is installed and ready.");});

function dismissStartup(){const screen=els.startupScreen;if(!screen)return;screen.classList.add("is-leaving");screen.setAttribute("aria-hidden","true");document.body.classList.remove("app-booting");setTimeout(()=>screen.remove(),550);}
async function startApp(){const started=performance.now(),quranReady=loadQuran(),fontsReady=document.fonts?.ready||Promise.resolve();await Promise.race([Promise.allSettled([quranReady,fontsReady]),new Promise(resolve=>setTimeout(resolve,6000))]);const minimumWait=Math.max(0,900-(performance.now()-started));setTimeout(dismissStartup,minimumWait);}
document.documentElement.style.setProperty("--arabic-size",`${state.arabicSize}rem`);buildIndex();syncReaderViewControls();if(state.readerView==="mushaf")renderMushafPage(state.currentPage,{scroll:false,history:false,manual:true});else renderSurah(1,1,{scroll:false,history:false});renderSavedItems();startApp();if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./service-worker.js").catch(()=>{}));
function registerAgentTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController(),register=tool=>Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});register({name:"navigate_to_ayah",title:"Open a Quran ayah",description:"Open a specific Quran surah and ayah in the visible AyahFlow reader.",inputSchema:{type:"object",properties:{surah:{type:"integer",minimum:1,maximum:114},ayah:{type:"integer",minimum:1}},required:["surah","ayah"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){const surah=Number(input?.surah),ayah=Number(input?.ayah);if(!Number.isInteger(surah)||!Number.isInteger(ayah)||!state.quran[surah-1]?.ayahs[ayah-1])throw new Error("That surah and ayah are not available.");stopDemo();renderSurah(surah,ayah);return{surah,ayah,name:state.quran[surah-1].name};}});register({name:"start_guided_recitation_demo",title:"Start guided recitation demo",description:"Start the visible Al-Fatihah demo with automatic ayah and word highlighting.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){setMode("follow");startDemo();return{status:"playing",surah:1,ayah:1};}});register({name:"search_quran",title:"Search the Quran",description:"Search AyahFlow by English, Arabic, surah name, or verse reference.",inputSchema:{type:"object",properties:{query:{type:"string"}},required:["query"],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){runSearch(String(input?.query||""));els.searchDialog.showModal();return{query:input.query};}});}
registerAgentTools();
